import json,hashlib,re
p='/workspace/scratch/volume4/batch329-338.json';d=json.load(open(p))
for page in d['pages']:
 for x in page['paragraphs']:
  x['ar']=x['ar'].replace('وإن لم يعرض ذاته','وإن لم يفرض ذاته')
  x['sha256']=hashlib.sha256(x['ar'].encode()).hexdigest()
by={x['id']:x for page in d['pages'] for x in page['paragraphs']}
for u in d['units']:
 u['ar']=' '.join(by[s]['ar'] for s in u['source_ids'])
 u['ru']=u['ru'].strip().replace('отвлекаясь от того, что сохраняет его его Создатель','отвлекаясь от сохранения его Создателем').replace('тот вдруг неожиданно входит','тот неожиданно входит').replace('ибо в сердце достигает чистое','ибо его сердца достигает чистое').replace('Он даёт ему созерцать восхождение результатов действий к Его действиям, восхождение Его действий к Его именам и атрибутам','Он даёт ему созерцать, как всё сделанное восходит к Его действиям, а Его действия — к Его именам и атрибутам')
 assert re.findall(r'\{[^}]*\}',u['ar'])==re.findall(r'\{[^}]*\}',u['ru']),u['id']
 assert u['ar']==' '.join(by[s]['ar'] for s in u['source_ids'])
allids=[s for u in d['units'] for s in u['source_ids']]
assert len(allids)==len(set(allids))==len(by)
assert [x['printed_page'] for x in d['pages']]==list(range(329,339))
d['review_notes']=[{'type':'self_review','note':'Каждое изображение страниц 329–338 реально открыто через view_image и прочитано; арабский текст набран вручную по изображениям без OCR. Подстрочные издательские примечания и их цифровые маркеры исключены.'},{'type':'semantic_comparison','note':'Выполнено смысловое сопоставление перевода с прочитанным арабским текстом всех десяти страниц: сохранены разграничения фана как гибели и как поглощённости, существования и пребывания, знания/познания/непосредственного видения/обретения, авторские возражения и оба развёрнутых примера. Внутренние переходящие абзацы объединены.'},{'type':'russian_reading','note':'Отдельно прочитан полный русский текст после сборки единиц; устранены неловкость на стыке 330–331, повтор на стыке 335–336 и грамматическая ошибка на 338.'},{'type':'final_comparison','note':'Выполнена заключительная сверка арабского и русского текстов с ранее открытыми изображениями, повторно увеличены и открыты 332 и 336. На 332 уточнено чтение «يفرض»; арабская запись исправлена. Проверены SHA-256, полное однократное покрытие source_ids и идентичность коранических фрагментов в фигурных скобках. Это самопроверка исполнителя; независимой человеческой проверки не было.'},{'type':'open_issue','note':'Заключительный термин 338 «المشهد الروحي الذاتي» передан как духовное созерцание, затрагивающее саму сущность человека. Для окончательной терминологической унификации желательно сопоставление с дальнейшим разъяснением 339; текст 339 в пакет не импортирован.'}]
json.dump(d,open(p,'w'),ensure_ascii=False,indent=2)
